<?php
namespace qqworld_collector\module\collecting\magics; use qqworld_collector\lib; class parse_tmall_product extends lib { public function get_product_images($file) { $images = array(); $preg = preg_match('/<ul id="J_UlThumb" class="tb\-thumb tm\-clear">([\s\S]*?)<\/ul>/', $file, $match); if ($preg) { $preg = preg_match_all('/<a href="#"><img src="(.*?)_60x60q90\.jpg" \/><\/a>/i', $match[1], $matches); if ($preg) { foreach ($matches[1] as $src) { $images[] = array('src' => 'http:' . $src); } } } return $images; } public function get_product_attributes($file, $variations) { $attributes = array(); $preg = preg_match('/<ul id="J_AttrUL">([\s\S]*?)<\/ul>/', $file, $match); if ($preg) { $preg = preg_match_all('/title="(.*?)">([^:]*)/i', str_replace('：', ':', $match[1]), $matches); if ($preg) { foreach ($matches[1] as $index => $title) { $attributes[] =array( 'name' => $matches[2][$index], 'options' => str_replace('&nbsp;', '', $title), 'visible' => 1 ); } } } if (!empty($variations)) foreach ($variations as $title => $variation) { foreach ($attributes as $index => $attribute) { if ($title == $attribute['name']) { unset($attributes[$index]); $attributes[] = array( 'name' => $title, 'options' => implode(' | ', $variation), 'variation' => 1, 'visible' => 1 ); } } } return $attributes; } public function get_product_variations($file) { $variations = array(); $preg = preg_match_all('/<dl class="tb-prop tm-sale-prop.*?>([\s\S]*?)<\/dl>/', $file, $matches); if ($preg) { foreach ($matches[1] as $variation) { $preg = preg_match('/<dt class="tb\-metatit">(.*?)<\/dt>/i', $variation, $match); if ($preg) { $title = $match[1]; $variations[$title] = array(); $preg = preg_match_all('/<li data-value="(.*?)".*?>[\s\S]*?<span>(.*?)<\/span>/i', $variation, $options); if ($preg) { foreach ($options[1] as $index => $id) { $variations[$title][$id] = $options[2][$index]; } } } } } return $variations; } function get_variations($json, $initJson, $variations) { $results = array(); if (isset($json['valItemInfo'])) { $priceInfo = $initJson && isset($initJson['defaultModel']['itemPriceResultDO']['priceInfo']) ? $initJson['defaultModel']['itemPriceResultDO']['priceInfo'] : false; $skuList = $json['valItemInfo']['skuList']; $skuMap = $json['valItemInfo']['skuMap']; if (!empty($skuList)) foreach ($skuList as $sku) { $pvs = $sku['pvs']; $vars = explode(';', $pvs); $attributes = array(); foreach ($vars as $var) { foreach ($variations as $title => $options) { if (isset($options[$var])) { $attributes[] = array( 'name' => $title, 'option' => $options[$var] ); break; } } } $result = array( 'in_stock' => true, 'regular_price' => $skuMap[";{$pvs};"]['price'], 'attributes' => $attributes ); if ($priceInfo) { $skuId = $skuMap[";{$pvs};"]['skuId']; $skuInfo = $priceInfo[$skuId]; if (isset($skuInfo['promotionList'][0]['price'])) { $result['sale_price'] = intval($skuInfo['promotionList'][0]['price']); } } $results[] = $result; } } return $results; } public function get_description($json, $download_args) { $description = ''; $descs = array('descUrl', 'httpsDescUrl'); foreach ($descs as $desc) { if ( isset($json['api']) && isset($json['api'][$desc]) ) { $descUrl = 'http:' . $json['api'][$desc]; $results = apply_filters( 'qqworld-collector-download-from-url', $descUrl, $download_args); $description = $results['file']; $description = stripslashes(preg_replace('/var desc=\'([\s\S]*?)\';/i', '$1', $description)); if (strstr($description, 'function') === false) break; } } return $description; } public function parse($url, $args) { $download_args = array( 'charset' => 'auto', 'headers' => $args['singular']['request']['headers'] ); $results = apply_filters( 'qqworld-collector-download-from-url', $url, $download_args ); $file = $results['file']; $preg = preg_match('/TShop\.Setup\(([\s\S]*?)\);/i', $file, $match); if ($preg) { $json = json_decode($match[1], true); $type = isset($json['valItemInfo']) ? 'variable' : 'simple'; $variations = $this->get_product_variations($file); $product = array( 'title' => $json['itemDO']['title'], 'type' => $type, 'enable_html_description' => true, 'description' => $this->get_description($json, $download_args), 'images' => $this->get_product_images($file), 'attributes' => $this->get_product_attributes($file, $variations) ); $initApi = 'https:' . $json['initApi']; $results = apply_filters( 'qqworld-collector-download-from-url', $initApi, $download_args ); $initJson = json_decode($results['file'], true); if ($type == 'variable') { $product['variations'] = $this->get_variations($json, $initJson, $variations); } else { $product['regular_price'] = $json['itemDO']['reservePrice']; $product['in_stock'] = true; if ($initJson && isset($initJson['defaultModel']['itemPriceResultDO']['priceInfo']['def']['promotionList']['price'])) { $product['sale_price'] = intval($initJson['defaultModel']['itemPriceResultDO']['priceInfo']['def']['promotionList']['price']); } } return $product; } return false; } } ?>